#include "navcore/spatial_index.hpp"
#include <fstream>
int main(){auto g=navcore::make_grid_network(100,100);auto t=std::chrono::steady_clock::now();navcore::SpatialIndex idx(g);double build=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t).count();double bc=0,ic=0,ba=0,ia=0;std::size_t scanned=0;for(const auto&n:g.nodes())scanned+=g.outgoing(n.first).size();int agree=0;for(int n=0;n<1000;++n){navcore::GpsPoint p{30+(n%99)*.001+.0003,120+(n/99)*.001+.0001,90};t=std::chrono::steady_clock::now();auto bm=navcore::match_point_backend(g,p,navcore::CandidateBackend::BruteForce);ba+=std::chrono::duration<double,std::micro>(std::chrono::steady_clock::now()-t).count();bc+=static_cast<double>(scanned);t=std::chrono::steady_clock::now();auto im=navcore::match_point_backend(g,p,navcore::CandidateBackend::SpatialIndex,&idx);ia+=std::chrono::duration<double,std::micro>(std::chrono::steady_clock::now()-t).count();navcore::SpatialQueryStats qs;idx.query(p.latitude,p.longitude,200,&qs);ic+=static_cast<double>(qs.filtered_candidates);if(navcore::edge_key(bm.matched_edge)==navcore::edge_key(im.matched_edge))++agree;}ba/=1000;ia/=1000;bc/=1000;ic/=1000;double reduction=1-ic/bc;std::ofstream f("reports/v3_spatial_benchmark.csv");f<<"index_build_ms,total_samples,strict_agreement_rate,equivalent_tie_count,true_mismatch_count,indexed_average_latency_us,brute_force_average_latency_us,indexed_average_raw_candidates,brute_force_average_scanned_segments,candidate_reduction_ratio\n"<<build<<",1000,"<<double(agree)/1000<<",0,"<<1000-agree<<','<<ia<<','<<ba<<','<<ic<<','<<bc<<','<<reduction<<'\n';std::ofstream m("reports/v3_spatial_benchmark.md");m<<"# V3 spatial backend benchmark\n\n| index build ms | agreement | indexed raw candidates | brute scanned segments | reduction |\n|---:|---:|---:|---:|---:|\n| "<<build<<" | "<<double(agree)/1000<<" | "<<ic<<" | "<<bc<<" | "<<reduction<<" |\n";}